head.script:
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 1. 샘플파일을 실행 후 상단의 항목(서비스구분등)을 여러번(3번이상) 클릭하여 소팅한다.
    //1. After executing the sample file, click the item (service classification etc.) at the top several times (more than 3 times) and sort it.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grd_Pay_temp_id_6').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grd_Pay_temp_id_6').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grd_Pay_temp_id_6').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grd_Pay_temp_id_6').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    // verify step 1. 정상적으로 소팅상태를 유지한다.(이전에는 3번이상 소팅을 할 경우 세로스크롤바가 생기고 소팅 풀림현상이 발생함,row가 늘어나는 현상발생)
    //1. Maintains the normal sorting state.(Previously, if you do more than 3 times of sorting, vertical scroll bar will occur, and sorting will occur).
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grd_Pay_scrollY_div').css('overflow-y') == 'hidden'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grd_Pay_scrollY_div').css('overflow-x') == 'hidden'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('grd_Pay_cell_0_0').innerText", "BTV");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('grd_Pay_cell_1_0').innerText == '선불이동전화'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('grd_Pay_cell_2_0').innerText == '일반이동전화'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('grd_Pay_cell_3_0').innerText == '일반이동전화'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('grd_Pay_cell_4_0').innerText == '일반이동전화'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.dst_Sum_out_data = [
        "520", "IRALL00", "B요금", "5000005560", "1", "01", "현금", "4", "T", "BTV", "39", "요금수납",
        "61600", "CRUSIM0", "USIM카드대금", "5000001397", "1", "52", "대체", "4", "C", "일반이동전화", "C1", "기기변경",
        "6600", "CRUSIM0", "USIM카드대금", "5000001398", "5", "52", "대체", "4", "C", "일반이동전화", "C1", "기기변경",
        "28700", "CRINR00", "요금보증보험료", "5000000134", "5", "01", "현금", "4", "C", "일반이동전화", "M1", "명의변경",
        "1102350", "CRWP001", "가상계좌송금", "5000000882", "5", "01", "현금", "4", "C", "이동전화", "91", "송금관리",
        "0", "CRG3P00", "3G 즉납가입비", "5000000011", "1", "01", "현금", "4", "C", "선불이동전화", "A1", "신규가입",
        "0", "CRG3P00", "3G 즉납가입비", "5000000011", "1", "01", "현금", "4", "C", "일반이동전화", "A1", "신규가입",
        "0", "CRG4P00", "4G 즉납가입비", "5000020761", "1", "01", "현금", "4", "C", "일반이동전화", "A1", "신규가입"
    ];
    dst_Sum_out.setData(dst_Sum_out_data);
    dst_Sum_out.setColumnFilter({
        type: 'func',
        colIndex: 0,
        key: function(cellData, tmpParam, rowIdx) {
            try {
                if (dst_Sum_out.getCellData(dst_Sum_out.getFilteredRowIndex(rowIdx), 'pay_cl_cd') != 5) {
                    return true;
                } else {
                    return false;
                }
            } catch (e) {
                return true;
            }
        },
        condition: 'and'
    });
    //Function unitTest
    //Created By: Sang.do
    //Created By: 29-Jan-2018
    //end unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
